Workflow: ${e.workflow?.name || 'unknown'}
Node: ${e.execution?.lastNodeExecuted || 'unknown'}
Error: ${e.execution?.error?.message || e.error?.message || 'unknown error'}` } }];

const cfg = $('Set - Global Config').first().json;
const formatSender = value => {
  const first = Array.isArray(value?.value) ? value.value[0] : Array.isArray(value) ? value[0] : value;
  if (first && typeof first === 'object') {
    const name = String(first.name || '').trim();
    const address = String(first.address || first.email || '').trim();
    if (name && address) return `${name} <${address}>`;
    return name || address || 'Unknown sender';
  }
  return String(first || '').trim() || 'Unknown sender';
};
return items.map(item => {
  const j = item.json || {};
  const binary = item.binary || {};
  const metadata = Array.isArray(j.attachments) ? j.attachments : Object.values(j.attachments || {});
  const binaryAttachments = Object.entries(binary).map(([property, data]) => ({ fileName: data.fileName || property, mimeType: data.mimeType || '', binaryProperty: property }));
  const candidates = binaryAttachments.length ? binaryAttachments : metadata.map(a => ({ fileName: a.fileName || a.filename || a.name || '', mimeType: a.mimeType || a.mime || '', binaryProperty: a.binaryProperty || a.property || 'data' }));
  const attachments = candidates.filter(a => { const name = String(a.fileName).toLowerCase(); const mime = String(a.mimeType).toLowerCase(); return mime === 'application/pdf' || name.endsWith('.pdf'); });
  return { json: { search_keyword: cfg.search_keyword, target_drive_folder_id: cfg.target_drive_folder_id, notification_channel: cfg.notification_channel, slack_channel_id: cfg.slack_channel_id, telegram_chat_id: cfg.telegram_chat_id, subject: j.subject || j.headers?.subject || '(No subject)', sender: formatSender(j.sender || j.from || j.headers?.from), body: j.textPlain || j.text || j.snippet || '', email_date: j.date || j.internalDate || j.headers?.date || '', attachments, pdf_count: attachments.length }, binary: Object.keys(binary).length ? binary : undefined };
});

return items.flatMap(item => (item.json.attachments || []).map(a => {
  const source = item.binary?.[a.binaryProperty];
  const date = new Date(item.json.email_date || '');
  const suffix = Number.isNaN(date.getTime()) ? '' : '_' + date.getUTCFullYear() + String(date.getUTCMonth() + 1).padStart(2, '0') + String(date.getUTCDate()).padStart(2, '0');
  const original = String(a.fileName || 'document.pdf');
  const fileName = original.replace(/\.pdf$/i, '') + suffix + '.pdf';
  if (!source) return { json: { ...item.json, fileName, mimeType: a.mimeType, binaryProperty: 'data', binary_error: 'Missing binary property: ' + a.binaryProperty } };
  return { json: { ...item.json, fileName, mimeType: a.mimeType, binaryProperty: 'data' }, binary: { data: source } };
}));

const sourceItems = $('Code - Split PDF Attachments').all();
const firstResult = items[0]?.json || {};
const firstSource = sourceItems[0]?.json || {};
const rows = items.map((item, index) => { const source = sourceItems[index]?.json || {}; const result = item.json || {}; return { source, result, sender: String(source.sender || 'Unknown sender').trim() || 'Unknown sender', subject: String(source.subject || '(No subject)').trim() || '(No subject)', driveLink: result.webViewLink || result.webContentLink || '' }; });
const uploadedIds = rows.filter(row => row.result.id && !row.result.error).map(row => row.result.id);
const emailGroups = new Map();
for (const row of rows) { const key = row.sender + '\u0000' + row.subject; const group = emailGroups.get(key) || { sender: row.sender, subject: row.subject, pdfCount: 0 }; if (row.result.id && !row.result.error) group.pdfCount += 1; emailGroups.set(key, group); }
return [{ json: { ...firstSource, ...firstResult, email_summaries: [...emailGroups.values()], file_summaries: rows.map(row => ({ sender: row.sender, subject: row.subject, driveLink: row.driveLink, uploaded: Boolean(row.result.id && !row.result.error) })), uploaded_count: uploadedIds.length, uploaded_ids: uploadedIds, pdf_count: rows.length, upload_status: uploadedIds.length ? 'uploaded' : 'not_uploaded' } }];

const j = items[0]?.json || {};
const files = Array.isArray(j.file_summaries) ? j.file_summaries : [];
const fallback = files.length ? files : [{ sender: String(j.sender || 'Unknown sender').trim() || 'Unknown sender', subject: String(j.subject || '(No subject)').trim() || '(No subject)', driveLink: '', uploaded: false }];
const lines = fallback.map((file, index) => { const link = file.driveLink ? `\n   PDF: ${file.driveLink}` : ''; const status = file.uploaded === false && !file.driveLink ? ' [upload unavailable]' : ''; return `${index + 1}. ${file.sender}\n   ${file.subject}${status}${link}`; });
const total = Number.isFinite(Number(j.uploaded_count)) ? Number(j.uploaded_count) : fallback.filter(file => file.uploaded).length;
const text = ['Gmail PDF intake', '', ...lines, '', `Uploaded: ${total} PDF${total === 1 ? '' : 's'}`].join('\n');
return [{ json: { ...j, notification_text: text } }];
